import React from 'react';
import { StatusBar } from 'react-native';
import { NavigationContainer } from '@react-navigation/native';
import { createNativeStackNavigator } from '@react-navigation/native-stack';
import { AppProvider } from './src/context/AppContext';

import HomeScreen from './src/screens/HomeScreen';
import ProductDetailScreen from './src/screens/ProductDetailScreen';
import CartScreen from './src/screens/CartScreen';
import LoginScreen from './src/screens/LoginScreen';
import RegisterScreen from './src/screens/RegisterScreen';
import OrderHistoryScreen from './src/screens/OrderHistoryScreen';
import ProfileScreen from './src/screens/ProfileScreen';
import AdminScreen from './src/screens/AdminScreen';

const Stack = createNativeStackNavigator();

export default function App() {
  return (
    <AppProvider>
      <NavigationContainer>
        <StatusBar barStyle="light-content" backgroundColor="#6F4E37" />
        <Stack.Navigator
          initialRouteName="Home"
          screenOptions={{
            headerStyle: { backgroundColor: '#6F4E37' },
            headerTintColor: '#FFFFFF',
            headerTitleStyle: { fontWeight: 'bold' },
          }}
        >
          <Stack.Screen
            name="Home"
            component={HomeScreen}
            options={{ title: 'SÃ n F&B TrÃ  Sá»¯a & CÃ  PhÃª', headerShown: false }}
          />
          <Stack.Screen
            name="ProductDetail"
            component={ProductDetailScreen}
            options={{ title: 'TÃ¹y chá»‰nh & ÄÃ¡nh giÃ¡ mÃ³n' }}
          />
          <Stack.Screen
            name="Cart"
            component={CartScreen}
            options={{ title: 'Giá» hÃ ng & Thanh toÃ¡n' }}
          />
          <Stack.Screen
            name="Login"
            component={LoginScreen}
            options={{ title: 'ÄÄƒng nháº­p há»‡ thá»‘ng' }}
          />
          <Stack.Screen
            name="Register"
            component={RegisterScreen}
            options={{ title: 'ÄÄƒng kÃ½ TÃ i khoáº£n / Äá»‘i tÃ¡c' }}
          />
          <Stack.Screen
            name="OrderHistory"
            component={OrderHistoryScreen}
            options={{ title: 'Tiáº¿n trÃ¬nh & Lá»‹ch sá»­ Ä‘Æ¡n hÃ ng' }}
          />
          <Stack.Screen
            name="Profile"
            component={ProfileScreen}
            options={{ title: 'Há»“ sÆ¡ cÃ¡ nhÃ¢n & GPS' }}
          />
          <Stack.Screen
            name="Admin"
            component={AdminScreen}
            options={{ title: 'Quáº£n trá»‹ Cá»­a hÃ ng & SÃ n' }}
          />
        </Stack.Navigator>
      </NavigationContainer>
    </AppProvider>
  );
}

import { registerRootComponent } from 'expo';

import App from './App';

// registerRootComponent calls AppRegistry.registerComponent('main', () => App);
// It also ensures that whether you load the app in Expo Go or in a native build,
// the environment is set up appropriately
registerRootComponent(App);

import axios from 'axios';

/**
 * LÆ¯U Ã Cáº¤U HÃŒNH Äá»ŠA CHá»ˆ IP KHI CHáº Y THá»°C Táº¾:
 * - MÃ¡y áº£o Android (Android Emulator): DÃ¹ng 'http://10.0.2.2:8080/trasua_api'
 * - MÃ¡y áº£o iOS hoáº·c cháº¡y Web: DÃ¹ng 'http://localhost:8080/trasua_api'
 * - Äiá»‡n thoáº¡i tháº­t (quÃ©t QR Expo Go): Äá»•i thÃ nh IPv4 LAN cá»§a mÃ¡y tÃ­nh (VD: 'http://192.168.1.15:8080/trasua_api')
 */
export const BASE_URL = 'http://192.168.1.8/trasua_api';

export const API_ENDPOINTS = {
  AUTH: `${BASE_URL}/auth.php`,
  PRODUCTS: `${BASE_URL}/products.php`,
  VOUCHERS: `${BASE_URL}/vouchers.php`,
  ORDERS: `${BASE_URL}/orders.php`,
  REVIEWS: `${BASE_URL}/reviews.php`,
};

export const apiClient = axios.create({
  baseURL: BASE_URL,
  timeout: 8000,
  headers: {
    'Content-Type': 'application/json',
    Accept: 'application/json',
  },
});

export const CATEGORIES = [ 'Táº¥t cáº£', 'TrÃ sá»¯a', 'CÃ phÃª', 'TrÃ trÃ¡i cÃ¢y', 'ÄÃ¡ xay', ];
export const SIZES = [ { id: 'S', label: 'Size S', price: 0 }, { id: 'M', label: 'Size M', price: 5000 }, { id: 'L', label: 'Size L', price: 10000 }, ];
export const SUGAR_LEVELS = ['0%', '30%', '50%', '70%', '100%'];
export const ICE_LEVELS = ['KhÃ´ng Ä‘Ã¡', '30% Ä‘Ã¡', '70% Ä‘Ã¡', '100% Ä‘Ã¡'];
export const TOPPINGS = [ { id: 't1', name: 'TrÃ¢n chÃ¢u Ä‘Æ°á»ng Ä‘en', price: 5000 }, { id: 't2', name: 'TrÃ¢n chÃ¢u tráº¯ng giÃ²n', price: 5000 }, { id: 't3', name: 'Kem phÃ´ mai Macchiato', price: 10000 }, { id: 't4', name: 'Pudding trá»©ng', price: 7000 }, { id: 't5', name: 'Tháº¡ch sÆ°Æ¡ng sÃ¡o', price: 5000 }, { id: 't6', name: 'ÄÃ o ngÃ¢m giÃ²n', price: 8000 }, ];
export const ORDER_STATUS_STEPS = [ 'Äang chuáº©n bá»‹', 'Chá» tÃ i xáº¿ nháº­n', 'Äang giao hÃ ng', 'HoÃ n táº¥t', ];
export const VIRTUAL_MAP_LOCATIONS = [ { id: 'loc1', title: 'Trung tÃ¢m BiÃªn HÃ²a', address: '120 VÃµ Thá»‹ SÃ¡u, P. Thá»‘ng Nháº¥t, TP. BiÃªn HÃ²a, Äá»“ng Nai', coords: { latitude: 10.9453, longitude: 106.8243 }, }, { id: 'loc2', title: 'ÄÆ°á»ng Äá»“ng Khá»Ÿi', address: '255 Äá»“ng Khá»Ÿi, P. TÃ¢n Hiá»‡p, TP. BiÃªn HÃ²a, Äá»“ng Nai', coords: { latitude: 10.9574, longitude: 106.8426 }, }, { id: 'loc3', title: 'Khu Vincom Pháº¡m VÄƒn Thuáº­n', address: '1096 Pháº¡m VÄƒn Thuáº­n, P. TÃ¢n Mai, TP. BiÃªn HÃ²a, Äá»“ng Nai', coords: { latitude: 10.9512, longitude: 106.8351 }, }, { id: 'loc4', title: 'Khu vá»±c Bá»­u Long', address: 'ÄÆ°á»ng Huá»³nh VÄƒn Nghá»‡, P. Bá»­u Long, TP. BiÃªn HÃ²a, Äá»“ng Nai', coords: { latitude: 10.9689, longitude: 106.8012 }, }, ];
export const FALLBACK_PRODUCTS = [ { id: 1, store_id: 1, storeName: 'Gong Cha BiÃªn HÃ²a', name: 'TrÃ Sá»¯a TrÃ¢n ChÃ¢u ÄÆ°á»ng Äen', category: 'TrÃ sá»¯a', basePrice: 45000, discountPrice: 35000, image: 'https://images.unsplash.com/photo-1558857563-b371033873b8?w=600', description: 'Sá»¯a tÆ°Æ¡i thanh trÃ¹ng káº¿t há»£p trÃ¢n chÃ¢u náº¥u Ä‘Æ°á»ng Ä‘en dáº»o má»m.', isBestSeller: true, isAvailable: true, soldCount: 42, avgRating: 4.9, reviewCount: 12, }, { id: 2, store_id: 1, storeName: 'Gong Cha BiÃªn HÃ²a', name: 'TrÃ Sá»¯a Khoai MÃ´n Kem Trá»©ng', category: 'TrÃ sá»¯a', basePrice: 50000, discountPrice: 0, image: 'https://images.unsplash.com/photo-1576092768241-dec231879fc3?w=600', description: 'Khoai mÃ´n nghiá»n bÃ©o ngáº­y phá»§ lá»›p kem trá»©ng khÃ² lá»­a thÆ¡m lá»«ng.', isBestSeller: true, isAvailable: true, soldCount: 28, avgRating: 4.8, reviewCount: 8, }, { id: 3, store_id: 1, storeName: 'Gong Cha BiÃªn HÃ²a', name: 'TrÃ ÄÃ o Cam Sáº£', category: 'TrÃ trÃ¡i cÃ¢y', basePrice: 40000, discountPrice: 32000, image: 'https://images.unsplash.com/photo-1556679343-c7306c1976bc?w=600', description: 'HÆ°Æ¡ng vá»‹ thanh mÃ¡t tá»« Ä‘Ã o ngÃ¢m giÃ²n, cam vÃ ng vÃ sáº£ tÆ°Æ¡i.', isBestSeller: true, isAvailable: true, soldCount: 35, avgRating: 4.7, reviewCount: 6, }, { id: 4, store_id: 2, storeName: 'Highlands Coffee & Tea', name: 'CÃ PhÃª Phin Sá»¯a ÄÃ¡', category: 'CÃ phÃª', basePrice: 35000, discountPrice: 29000, image: 'https://images.unsplash.com/photo-1514432324607-a09d9b4aefdd?w=600', description: 'Háº¡t Robusta rang má»™c pha phin truyá»n thá»‘ng cÃ¹ng sá»¯a Ä‘áº·c ngá»t dá»‹u.', isBestSeller: true, isAvailable: true, soldCount: 50, avgRating: 5.0, reviewCount: 19, }, ];
export const FALLBACK_VOUCHERS = [ { id: 1, store_id: null, code: 'GIAM10K', title: 'Giáº£m 10.000Ä‘ cho Ä‘Æ¡n tá»« 40.000Ä‘', type: 'fixed', value: 10000, minOrder: 40000, maxDiscount: 10000, isActive: true, }, { id: 2, store_id: null, code: 'FREESHIP', title: 'Trá»£ giÃ¡ 15.000Ä‘ phÃ­ giao hÃ ng cho Ä‘Æ¡n tá»« 60.000Ä‘', type: 'fixed', value: 15000, minOrder: 60000, maxDiscount: 15000, isActive: true, }, { id: 3, store_id: 1, storeName: 'Gong Cha BiÃªn HÃ²a', code: 'GONGCHA15', title: 'Giáº£m 15.000Ä‘ cho Ä‘Æ¡n Gong Cha tá»« 50.000Ä‘', type: 'fixed', value: 15000, minOrder: 50000, maxDiscount: 15000, isActive: true, }, ];

import React, { createContext, useState, useEffect, useContext } from 'react';
import AsyncStorage from '@react-native-async-storage/async-storage';
import { apiClient, API_ENDPOINTS } from '../constants/api';
import { FALLBACK_PRODUCTS, FALLBACK_VOUCHERS } from '../constants/data';

const AppContext = createContext();

export const AppProvider = ({ children }) => {
  const [currentUser, setCurrentUser] = useState(null);
  const [products, setProducts] = useState([]);
  const [stores, setStores] = useState([]);
  const [warnings, setWarnings] = useState([]);
  const [vouchers, setVouchers] = useState([]);
  const [orders, setOrders] = useState([]);
  const [reviews, setReviews] = useState([]);
  const [cart, setCart] = useState([]);
  const [favorites, setFavorites] = useState([]);
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    loadLocalStorage();
    fetchAllData();
  }, []);

  const loadLocalStorage = async () => {
    try {
      const savedUser = await AsyncStorage.getItem('@currentUser');
      const savedCart = await AsyncStorage.getItem('@guestCart');
      const savedFavs = await AsyncStorage.getItem('@favorites');

      if (savedUser) setCurrentUser(JSON.parse(savedUser));
      if (savedCart) setCart(JSON.parse(savedCart));
      if (savedFavs) setFavorites(JSON.parse(savedFavs));
    } catch (error) {
      console.log('Lá»—i Ä‘á»c AsyncStorage:', error.message);
    }
  };

  const syncCartToStorage = async (newCart) => {
    setCart(newCart);
    try {
      await AsyncStorage.setItem('@guestCart', JSON.stringify(newCart));
    } catch (e) {
      console.log('Lá»—i lÆ°u giá» hÃ ng:', e.message);
    }
  };

  // 1. Äá»’NG Bá»˜ Dá»® LIá»†U Tá»ª MYSQL XAMPP
  const fetchAllData = async () => {
    setLoading(true);
    try {
      const [prodRes, voucherRes, orderRes, reviewRes] = await Promise.all([
        apiClient.get(API_ENDPOINTS.PRODUCTS),
        apiClient.get(API_ENDPOINTS.VOUCHERS),
        apiClient.get(API_ENDPOINTS.ORDERS),
        apiClient.get(API_ENDPOINTS.REVIEWS),
      ]);

      if (prodRes.data?.success) {
        setProducts(prodRes.data.products || []);
        setStores(prodRes.data.stores || []);
        setWarnings(prodRes.data.warnings || []);
      }
      if (voucherRes.data?.success) {
        setVouchers(voucherRes.data.vouchers || []);
      }
      if (orderRes.data?.success) {
        setOrders(orderRes.data.orders || []);
      }
      if (reviewRes.data?.success) {
        setReviews(reviewRes.data.reviews || []);
      }
    } catch (error) {
      console.log('KhÃ´ng káº¿t ná»‘i Ä‘Æ°á»£c XAMPP, dÃ¹ng dá»¯ liá»‡u dá»± phÃ²ng:', error.message);
      if (products.length === 0) setProducts(FALLBACK_PRODUCTS);
      if (vouchers.length === 0) setVouchers(FALLBACK_VOUCHERS);
    } finally {
      setLoading(false);
    }
  };

  // 2. XÃC THá»°C & 4 PHÃ‚N QUYá»€N (CUSTOMER, VENDOR, SHIPPER, ADMIN)
  const login = async (username, password) => {
    try {
      const res = await apiClient.post(API_ENDPOINTS.AUTH, {
        action: 'login',
        username,
        password,
      });
      if (res.data?.success) {
        setCurrentUser(res.data.user);
        await AsyncStorage.setItem('@currentUser', JSON.stringify(res.data.user));
        return { success: true, user: res.data.user };
      }
      return { success: false, message: res.data?.message || 'ÄÄƒng nháº­p tháº¥t báº¡i' };
    } catch (error) {
      return {
        success: false,
        message: 'KhÃ´ng thá»ƒ káº¿t ná»‘i mÃ¡y chá»§ XAMPP (Cá»•ng 8080). Vui lÃ²ng kiá»ƒm tra Apache & MySQL!',
      };
    }
  };

  const register = async (payload) => {
    try {
      const res = await apiClient.post(API_ENDPOINTS.AUTH, {
        action: 'register',
        ...payload,
      });
      if (res.data?.success) {
        setCurrentUser(res.data.user);
        await AsyncStorage.setItem('@currentUser', JSON.stringify(res.data.user));
        await fetchAllData();
        return { success: true, user: res.data.user };
      }
      return { success: false, message: res.data?.message || 'ÄÄƒng kÃ½ tháº¥t báº¡i' };
    } catch (error) {
      return { success: false, message: 'Lá»—i káº¿t ná»‘i XAMPP khi Ä‘Äƒng kÃ½ tÃ i khoáº£n!' };
    }
  };

  const updateProfile = async (payload) => {
    try {
      const res = await apiClient.post(API_ENDPOINTS.AUTH, {
        action: 'update_profile',
        ...payload,
      });
      if (res.data?.success) {
        setCurrentUser(res.data.user);
        await AsyncStorage.setItem('@currentUser', JSON.stringify(res.data.user));
        return { success: true, message: res.data.message };
      }
      return { success: false, message: res.data?.message || 'Cáº­p nháº­t tháº¥t báº¡i' };
    } catch (error) {
      return { success: false, message: 'Lá»—i káº¿t ná»‘i mÃ¡y chá»§ khi cáº­p nháº­t há»“ sÆ¡!' };
    }
  };

  const logout = async () => {
    setCurrentUser(null);
    await AsyncStorage.removeItem('@currentUser');
  };

  // 3. DANH SÃCH YÃŠU THÃCH
  const toggleFavorite = async (productId) => {
    const exists = favorites.includes(productId);
    const updated = exists
      ? favorites.filter((id) => id !== productId)
      : [...favorites, productId];
    setFavorites(updated);
    await AsyncStorage.setItem('@favorites', JSON.stringify(updated));
  };

  // 4. QUáº¢N LÃ GIá»Ž HÃ€NG
  const addToCart = (item) => {
    const toppingsKey = (item.toppings || []).slice().sort().join(',');
    const signature = `${item.productId}_${item.size}_${item.sugar}_${item.ice}_${toppingsKey}`;

    const existingIndex = cart.findIndex((c) => c.signature === signature);
    let updatedCart = [...cart];

    if (existingIndex > -1) {
      updatedCart[existingIndex].quantity += item.quantity;
      updatedCart[existingIndex].totalPrice =
        updatedCart[existingIndex].quantity * updatedCart[existingIndex].unitPrice;
    } else {
      updatedCart.push({
        ...item,
        cartItemId: Date.now().toString() + Math.random().toString(36).substring(2, 6),
        signature,
      });
    }
    syncCartToStorage(updatedCart);
  };

  const updateCartQuantity = (cartItemId, delta) => {
    const updatedCart = cart
      .map((item) => {
        if (item.cartItemId === cartItemId) {
          const newQty = item.quantity + delta;
          if (newQty <= 0) return null;
          return {
            ...item,
            quantity: newQty,
            totalPrice: newQty * item.unitPrice,
          };
        }
        return item;
      })
      .filter(Boolean);
    syncCartToStorage(updatedCart);
  };

  const removeFromCart = (cartItemId) => {
    const updatedCart = cart.filter((item) => item.cartItemId !== cartItemId);
    syncCartToStorage(updatedCart);
  };

  const clearCart = () => {
    syncCartToStorage([]);
  };

  const reOrder = (oldItems) => {
    if (!Array.isArray(oldItems) || oldItems.length === 0) return;
    let updatedCart = [...cart];
    oldItems.forEach((item) => {
      updatedCart.push({
        ...item,
        cartItemId: Date.now().toString() + Math.random().toString(36).substring(2, 6),
        signature: `${item.productId}_${item.size}_${item.sugar}_${item.ice}_${(item.toppings || []).join(',')}`,
      });
    });
    syncCartToStorage(updatedCart);
  };

  // 5. Äáº¶T HÃ€NG & LUá»’NG SHIPPER / Cá»¬A HÃ€NG Cáº¬P NHáº¬T TRáº NG THÃI
  const createOrder = async (orderPayload) => {
    try {
      const res = await apiClient.post(API_ENDPOINTS.ORDERS, {
        action: 'create',
        ...orderPayload,
      });
      if (res.data?.success) {
        clearCart();
        await fetchAllData();
        return { success: true, orderCode: res.data.orderCode };
      }
      return { success: false, message: res.data?.message || 'KhÃ´ng thá»ƒ táº¡o Ä‘Æ¡n hÃ ng' };
    } catch (error) {
      return { success: false, message: 'Lá»—i káº¿t ná»‘i XAMPP khi táº¡o Ä‘Æ¡n hÃ ng!' };
    }
  };

  const updateOrderStatus = async (orderCode, status, shipperInfo = null) => {
    try {
      const payload = {
        action: 'update_status',
        orderCode,
        status,
      };
      if (shipperInfo) {
        payload.shipper_username = shipperInfo.username;
        payload.shipperName = shipperInfo.fullName;
      }
      const res = await apiClient.post(API_ENDPOINTS.ORDERS, payload);
      if (res.data?.success) {
        await fetchAllData();
        return { success: true, message: res.data.message };
      }
      return { success: false, message: res.data?.message };
    } catch (error) {
      return { success: false, message: 'Lá»—i káº¿t ná»‘i khi cáº­p nháº­t tráº¡ng thÃ¡i Ä‘Æ¡n!' };
    }
  };

  // 6. VENDOR CRUD Sáº¢N PHáº¨M & ADMIN Gá»¬I Cáº¢NH CÃO VI PHáº M
  const saveProduct = async (productPayload) => {
    try {
      const res = await apiClient.post(API_ENDPOINTS.PRODUCTS, {
        action: 'save',
        role: currentUser?.role || 'vendor',
        ...productPayload,
      });
      if (res.data?.success) {
        await fetchAllData();
        return { success: true, message: res.data.message };
      }
      return { success: false, message: res.data?.message };
    } catch (error) {
      return { success: false, message: 'Lá»—i káº¿t ná»‘i mÃ¡y chá»§ khi lÆ°u sáº£n pháº©m!' };
    }
  };

  const toggleProductAvailability = async (id, isAvailable) => {
    try {
      const res = await apiClient.post(API_ENDPOINTS.PRODUCTS, {
        action: 'toggle_availability',
        role: currentUser?.role || 'vendor',
        id,
        isAvailable,
      });
      if (res.data?.success) {
        await fetchAllData();
        return { success: true };
      }
      return { success: false, message: res.data?.message };
    } catch (error) {
      return { success: false };
    }
  };

  const deleteProduct = async (id, reason = '') => {
    try {
      const res = await apiClient.post(API_ENDPOINTS.PRODUCTS, {
        action: 'delete',
        role: currentUser?.role || 'vendor',
        id,
        reason,
      });
      if (res.data?.success) {
        await fetchAllData();
        return { success: true, message: res.data.message };
      }
      return { success: false, message: res.data?.message };
    } catch (error) {
      return { success: false, message: 'Lá»—i khi xÃ³a sáº£n pháº©m!' };
    }
  };

  const sendWarningToStore = async ({ store_id, product_name, message }) => {
    try {
      const res = await apiClient.post(API_ENDPOINTS.PRODUCTS, {
        action: 'send_warning',
        store_id,
        product_name,
        message,
      });
      if (res.data?.success) {
        await fetchAllData();
        return { success: true, message: res.data.message };
      }
      return { success: false, message: res.data?.message };
    } catch (error) {
      return { success: false, message: 'Lá»—i káº¿t ná»‘i khi gá»­i cáº£nh cÃ¡o!' };
    }
  };

  const resolveStoreWarning = async (id) => {
    try {
      const res = await apiClient.post(API_ENDPOINTS.PRODUCTS, {
        action: 'resolve_warning',
        id,
      });
      if (res.data?.success) {
        await fetchAllData();
        return { success: true };
      }
      return { success: false };
    } catch (error) {
      return { success: false };
    }
  };

  // 7. QUáº¢N LÃ MÃƒ GIáº¢M GIÃ (VOUCHER TOÃ€N SÃ€N & VOUCHER Cá»¬A HÃ€NG)
  const saveVoucher = async (voucherPayload) => {
    try {
      const res = await apiClient.post(API_ENDPOINTS.VOUCHERS, {
        action: 'save',
        ...voucherPayload,
      });
      if (res.data?.success) {
        await fetchAllData();
        return { success: true, message: res.data.message };
      }
      return { success: false, message: res.data?.message };
    } catch (error) {
      return { success: false, message: 'Lá»—i káº¿t ná»‘i khi lÆ°u mÃ£ giáº£m giÃ¡!' };
    }
  };

  const deleteVoucher = async (id) => {
    try {
      const res = await apiClient.post(API_ENDPOINTS.VOUCHERS, {
        action: 'delete',
        id,
      });
      if (res.data?.success) {
        await fetchAllData();
        return { success: true, message: res.data.message };
      }
      return { success: false, message: res.data?.message };
    } catch (error) {
      return { success: false, message: 'Lá»—i khi xÃ³a mÃ£ giáº£m giÃ¡!' };
    }
  };

  // 8. ÄÃNH GIÃ Sáº¢N PHáº¨M SAU KHI MUA (VERIFIED REVIEW)
  const getEligibleOrderForReview = (productId) => {
    if (!currentUser) return null;
    const completedOrders = orders.filter(
      (o) =>
        o.username === currentUser.username &&
        o.status === 'HoÃ n táº¥t' &&
        Array.isArray(o.items) &&
        o.items.some((item) => Number(item.productId) === Number(productId))
    );

    for (const ord of completedOrders) {
      const alreadyReviewed = reviews.some(
        (r) =>
          r.orderCode === ord.orderCode &&
          Number(r.product_id) === Number(productId) &&
          r.username === currentUser.username
      );
      if (!alreadyReviewed) {
        return ord.orderCode;
      }
    }
    return null;
  };

  const addReview = async ({ orderCode, product_id, rating, comment }) => {
    if (!currentUser) {
      return { success: false, message: 'Vui lÃ²ng Ä‘Äƒng nháº­p Ä‘á»ƒ Ä‘Ã¡nh giÃ¡!' };
    }
    try {
      const res = await apiClient.post(API_ENDPOINTS.REVIEWS, {
        action: 'add',
        orderCode,
        product_id,
        username: currentUser.username,
        fullName: currentUser.fullName,
        rating,
        comment,
      });
      if (res.data?.success) {
        await fetchAllData();
        return { success: true, message: res.data.message };
      }
      return { success: false, message: res.data?.message };
    } catch (error) {
      return { success: false, message: 'Lá»—i káº¿t ná»‘i khi gá»­i Ä‘Ã¡nh giÃ¡!' };
    }
  };

  return (
    <AppContext.Provider
      value={{
        currentUser,
        products,
        stores,
        warnings,
        vouchers,
        orders,
        reviews,
        cart,
        favorites,
        loading,
        fetchAllData,
        login,
        register,
        updateProfile,
        logout,
        toggleFavorite,
        addToCart,
        updateCartQuantity,
        removeFromCart,
        clearCart,
        reOrder,
        createOrder,
        updateOrderStatus,
        saveProduct,
        toggleProductAvailability,
        deleteProduct,
        sendWarningToStore,
        resolveStoreWarning,
        saveVoucher,
        deleteVoucher,
        getEligibleOrderForReview,
        addReview,
      }}
    >
      {children}
    </AppContext.Provider>
  );
};

