import React, { useState, useEffect, useMemo, useCallback } from 'react';
import {
  View,
  Text,
  ScrollView,
  TouchableOpacity,
  TextInput,
  Image,
  StyleSheet,
  Alert,
  ActivityIndicator,
  Modal,
  RefreshControl,
} from 'react-native';
import * as Location from 'expo-location';
import { useApp } from '../context/AppContext';
import { VIRTUAL_MAP_LOCATIONS } from '../constants/data';

export default function CartScreen({ navigation }) {
  const {
    currentUser,
    cart,
    vouchers,
    updateCartQuantity,
    removeFromCart,
    clearCart,
    createOrder,
    fetchAllData,
  } = useApp();

  const [customerName, setCustomerName] = useState('');
  const [phone, setPhone] = useState('');
  const [address, setAddress] = useState('');
  const [note, setNote] = useState('');
  const [paymentMethod, setPaymentMethod] = useState('COD');

  const [voucherInput, setVoucherInput] = useState('');
  const [appliedVoucher, setAppliedVoucher] = useState(null);

  const [loadingGps, setLoadingGps] = useState(false);
  const [showVirtualMap, setShowVirtualMap] = useState(false);
  const [submittingOrder, setSubmittingOrder] = useState(false);
  const [refreshing, setRefreshing] = useState(false);

  const [qrModalVisible, setQrModalVisible] = useState(false);
  const [qrSecondsLeft, setQrSecondsLeft] = useState(120);
  const [pendingOrderCode, setPendingOrderCode] = useState('');
  const [verifyingBank, setVerifyingBank] = useState(false);

  const onRefresh = useCallback(async () => {
    setRefreshing(true);
    await fetchAllData();
    setRefreshing(false);
  }, [fetchAllData]);

  useEffect(() => {
    if (currentUser) {
      setCustomerName(currentUser.fullName || '');
      setPhone(currentUser.phone || '');
      setAddress(currentUser.address || '');
    }
  }, [currentUser]);

  useEffect(() => {
    if (!qrModalVisible) return;

    if (qrSecondsLeft <= 0) {
      setQrModalVisible(false);
      Alert.alert(
        'Háº¿t thá»i gian',
        'PhiÃªn mÃ£ QR Ä‘Ã£ háº¿t háº¡n. Vui lÃ²ng thanh toÃ¡n láº¡i!'
      );
      return;
    }

    const timer = setInterval(() => {
      setQrSecondsLeft((prev) => prev - 1);
    }, 1000);

    return () => clearInterval(timer);
  }, [qrModalVisible, qrSecondsLeft]);

  const formatCountdown = (secs) => {
    const mins = Math.floor(secs / 60);
    const remSecs = secs % 60;
    return `${mins < 10 ? '0' : ''}${mins}:${remSecs < 10 ? '0' : ''}${remSecs}`;
  };

  const subTotal = useMemo(() => {
    return cart.reduce((sum, item) => sum + item.totalPrice, 0);
  }, [cart]);

  const getEligibleSubTotalForVoucher = (voucher) => {
    if (!voucher) return 0;
    if (!voucher.store_id) return subTotal;
    return cart
      .filter((item) => Number(item.storeId) === Number(voucher.store_id))
      .reduce((sum, item) => sum + item.totalPrice, 0);
  };

  const discountAmount = useMemo(() => {
    if (!appliedVoucher) return 0;
    const targetSubTotal = getEligibleSubTotalForVoucher(appliedVoucher);
    if (targetSubTotal < appliedVoucher.minOrder) return 0;

    if (appliedVoucher.type === 'fixed') {
      return Math.min(appliedVoucher.value, targetSubTotal);
    }
    if (appliedVoucher.type === 'percent') {
      const rawDiscount = Math.round((targetSubTotal * appliedVoucher.value) / 100);
      return appliedVoucher.maxDiscount > 0
        ? Math.min(rawDiscount, appliedVoucher.maxDiscount)
        : rawDiscount;
    }
    return 0;
  }, [appliedVoucher, subTotal, cart]);

  const totalAmount = Math.max(0, subTotal - discountAmount);
  const formatCurrency = (val) => `${Number(val || 0).toLocaleString('vi-VN')}Ä‘`;

  const handleApplyVoucherCode = (codeToApply) => {
    const cleanCode = (codeToApply || voucherInput).trim().toUpperCase();
    if (!cleanCode) {
      Alert.alert('ThÃ´ng bÃ¡o', 'Vui lÃ²ng nháº­p mÃ£ giáº£m giÃ¡!');
      return;
    }

    const found = vouchers.find(
      (v) => v.code.toUpperCase() === cleanCode && v.isActive
    );

    if (!found) {
      Alert.alert('KhÃ´ng há»£p lá»‡', 'MÃ£ khÃ´ng tá»“n táº¡i hoáº·c Ä‘Ã£ háº¿t háº¡n!');
      return;
    }

    const eligibleAmount = getEligibleSubTotalForVoucher(found);

    if (found.store_id && eligibleAmount === 0) {
      Alert.alert(
        'ThÃ´ng bÃ¡o',
        `MÃ£ nÃ y chá»‰ Ã¡p dá»¥ng cho mÃ³n cá»§a quÃ¡n "${found.storeName || '#' + found.store_id}".`
      );
      return;
    }

    if (eligibleAmount < found.minOrder) {
      Alert.alert(
        'ChÆ°a Ä‘á»§ Ä‘iá»u kiá»‡n',
        `ÄÆ¡n tá»‘i thiá»ƒu tá»« ${formatCurrency(found.minOrder)}. Hiá»‡n táº¡i má»›i Ä‘áº¡t ${formatCurrency(eligibleAmount)}.`
      );
      return;
    }

    setAppliedVoucher(found);
    setVoucherInput(found.code);
    Alert.alert('ThÃ nh cÃ´ng', `ÄÃ£ Ã¡p dá»¥ng mÃ£: ${found.code}`);
  };

  const handleGetRealGPS = async () => {
    setLoadingGps(true);
    try {
      const { status } = await Location.requestForegroundPermissionsAsync();
      if (status !== 'granted') {
        setShowVirtualMap(true);
        setLoadingGps(false);
        return;
      }

      const loc = await Location.getCurrentPositionAsync({
        accuracy: Location.Accuracy.Balanced,
      });
      const { latitude, longitude } = loc.coords;

      const geo = await Location.reverseGeocodeAsync({ latitude, longitude });
      if (geo && geo.length > 0) {
        const place = geo[0];
        const formatted = [
          place.name || place.streetNumber,
          place.street,
          place.subregion || place.district,
          place.city || place.region,
        ]
          .filter(Boolean)
          .join(', ');

        setAddress(formatted || `Tá»a Ä‘á»™ (${latitude.toFixed(4)}, ${longitude.toFixed(4)})`);
      } else {
        setAddress(`Tá»a Ä‘á»™ (${latitude.toFixed(5)}, ${longitude.toFixed(5)})`);
      }
    } catch (error) {
      setShowVirtualMap(true);
    } finally {
      setLoadingGps(false);
    }
  };

  const submitFinalOrderToServer = async (generatedCode, paymentStatusLabel) => {
    const primaryStoreId = cart[0]?.storeId || 1;

    setSubmittingOrder(true);
    const res = await createOrder({
      orderCode: generatedCode,
      store_id: primaryStoreId,
      username: currentUser.username,
      customerName: customerName.trim(),
      phone: phone.trim(),
      address: address.trim(),
      note: note.trim(),
      paymentMethod,
      paymentStatus: paymentStatusLabel,
      voucherCode: appliedVoucher && discountAmount > 0 ? appliedVoucher.code : null,
      subTotal,
      discountAmount,
      totalAmount,
      items: cart,
    });
    setSubmittingOrder(false);

    if (res.success) {
      setAppliedVoucher(null);
      setVoucherInput('');
      Alert.alert(
        'Äáº·t hÃ ng thÃ nh cÃ´ng',
        `MÃ£ Ä‘Æ¡n: #${res.orderCode}\nCá»­a hÃ ng Ä‘ang chuáº©n bá»‹ mÃ³n cho báº¡n!`,
        [
          {
            text: 'Xem Ä‘Æ¡n hÃ ng',
            onPress: () => navigation.replace('OrderHistory'),
          },
        ]
      );
    } else {
      Alert.alert('Lá»—i', res.message);
    }
  };

  const handleCheckoutPress = async () => {
    if (cart.length === 0) {
      Alert.alert('Giá» hÃ ng trá»‘ng', 'Vui lÃ²ng chá»n mÃ³n trÆ°á»›c!');
      return;
    }

    if (!currentUser) {
      Alert.alert(
        'YÃªu cáº§u Ä‘Äƒng nháº­p',
        'Vui lÃ²ng Ä‘Äƒng nháº­p Ä‘á»ƒ hoÃ n táº¥t Ä‘áº·t Ä‘Æ¡n!',
        [
          { text: 'Há»§y', style: 'cancel' },
          {
            text: 'ÄÄƒng nháº­p',
            onPress: () => navigation.navigate('Login', { redirectTo: 'Cart' }),
          },
        ]
      );
      return;
    }

    if (!customerName.trim() || !phone.trim() || !address.trim()) {
      Alert.alert(
        'Thiáº¿u thÃ´ng tin',
        'Vui lÃ²ng nháº­p Ä‘áº§y Ä‘á»§ Há» tÃªn, Sá»‘ Ä‘iá»‡n thoáº¡i vÃ  Äá»‹a chá»‰ nháº­n hÃ ng!'
      );
      return;
    }

    const tempOrderCode = 'ORD' + Math.floor(100000 + Math.random() * 900000);

    if (paymentMethod === 'Chuyá»ƒn khoáº£n QR') {
      setPendingOrderCode(tempOrderCode);
      setQrSecondsLeft(120);
      setQrModalVisible(true);
      return;
    }

    await submitFinalOrderToServer(tempOrderCode, 'Thanh toÃ¡n tiá»n máº·t (COD)');
  };

  const handleConfirmQrPaymentSuccess = () => {
    setVerifyingBank(true);
    setTimeout(async () => {
      setVerifyingBank(false);
      setQrModalVisible(false);
      await submitFinalOrderToServer(
        pendingOrderCode,
        'ÄÃ£ thanh toÃ¡n qua QR'
      );
    }, 1200);
  };

  const vietQrImageUrl = useMemo(() => {
    const addInfo = encodeURIComponent(`THANHTOAN ${pendingOrderCode}`);
    const accName = encodeURIComponent('SAN FB TRA SUA BIEN HOA');
    return `https://img.vietqr.io/image/MB-0987654321-compact2.png?amount=${totalAmount}&addInfo=${addInfo}&accountName=${accName}`;
  }, [totalAmount, pendingOrderCode]);

  // Xá»¬ LÃ KHI GIá»Ž HÃ€NG TRá»NG
  if (cart.length === 0) {
    return (
      <View style={styles.emptyContainer}>
        <Text style={styles.emptyEmoji}>ðŸ›’</Text>
        <Text style={styles.emptyTitle}>Giá» hÃ ng Ä‘ang trá»‘ng</Text>
        <Text style={styles.emptySub}>
          Chá»n thÃªm mÃ³n trÃ  sá»¯a hoáº·c cÃ  phÃª báº¡n thÃ­ch nhÃ©!
        </Text>
        <TouchableOpacity
          style={styles.goHomeBtn}
          onPress={() => {
            if (navigation.canGoBack()) {
              navigation.popToTop(); // Xáº£ sáº¡ch stack vÃ  quay vá» Home gá»‘c
            } else {
              navigation.replace('Home');
            }
          }}
        >
          <Text style={styles.goHomeBtnText}>KHÃM PHÃ MENU</Text>
        </TouchableOpacity>
      </View>
    );
  }

  return (
    <View style={styles.container}>
      <ScrollView
        contentContainerStyle={styles.scrollContent}
        refreshControl={
          <RefreshControl refreshing={refreshing} onRefresh={onRefresh} colors={['#6F4E37']} />
        }
      >
        <View style={styles.sectionCard}>
          <View style={styles.sectionHeaderRow}>
            <Text style={styles.sectionTitle}>MÃ³n Ä‘Ã£ chá»n ({cart.length})</Text>
            <TouchableOpacity onPress={clearCart}>
              <Text style={styles.clearAllText}>XÃ³a táº¥t cáº£</Text>
            </TouchableOpacity>
          </View>

          {cart.map((item) => (
            <View key={item.cartItemId} style={styles.cartItem}>
              <Image source={{ uri: item.image }} style={styles.itemImg} />
              <View style={styles.itemInfo}>
                <Text style={styles.itemStore}>{item.storeName}</Text>
                <Text style={styles.itemName}>{item.name}</Text>
                <Text style={styles.itemOptions}>
                  Size {item.size} â€¢ {item.sugar} Ä‘Æ°á»ng â€¢ {item.ice}
                </Text>
                {item.toppings && item.toppings.length > 0 && (
                  <Text style={styles.itemToppings}>
                    + {item.toppings.join(', ')}
                  </Text>
                )}

                <View style={styles.itemBottomRow}>
                  <Text style={styles.itemTotalPrice}>
                    {formatCurrency(item.totalPrice)}
                  </Text>

                  <View style={styles.qtyBox}>
                    <TouchableOpacity
                      style={styles.qtyBtn}
                      onPress={() => updateCartQuantity(item.cartItemId, -1)}
                    >
                      <Text style={styles.qtyBtnText}>âˆ’</Text>
                    </TouchableOpacity>
                    <Text style={styles.qtyText}>{item.quantity}</Text>
                    <TouchableOpacity
                      style={styles.qtyBtn}
                      onPress={() => updateCartQuantity(item.cartItemId, 1)}
                    >
                      <Text style={styles.qtyBtnText}>+</Text>
                    </TouchableOpacity>

                    <TouchableOpacity
                      style={styles.removeBtn}
                      onPress={() => removeFromCart(item.cartItemId)}
                    >
                      <Text style={styles.removeBtnText}>ðŸ—‘ï¸</Text>
                    </TouchableOpacity>
                  </View>
                </View>
              </View>
            </View>
          ))}
        </View>

        <View style={styles.sectionCard}>
          <Text style={styles.sectionTitle}>MÃ£ giáº£m giÃ¡</Text>
          <View style={styles.voucherInputRow}>
            <TextInput
              style={styles.voucherInput}
              placeholder="Nháº­p mÃ£ Æ°u Ä‘Ã£i..."
              value={voucherInput}
              onChangeText={setVoucherInput}
