            />
            <TouchableOpacity
              style={styles.applyVoucherBtn}
              onPress={() => handleApplyVoucherCode(voucherInput)}
            >
              <Text style={styles.applyVoucherText}>Ãp dá»¥ng</Text>
            </TouchableOpacity>
          </View>

          <ScrollView horizontal showsHorizontalScrollIndicator={false}>
            {vouchers
              .filter((v) => v.isActive)
              .map((v) => {
                const isSelected = appliedVoucher?.code === v.code && discountAmount > 0;
                const eligibleAmt = getEligibleSubTotalForVoucher(v);
                const eligible = eligibleAmt >= v.minOrder && eligibleAmt > 0;
                return (
                  <TouchableOpacity
                    key={v.id || v.code}
                    style={[
                      styles.voucherTicket,
                      v.store_id && styles.voucherTicketStore,
                      isSelected && styles.voucherTicketActive,
                      !eligible && { opacity: 0.5 },
                    ]}
                    onPress={() => handleApplyVoucherCode(v.code)}
                  >
                    <Text style={styles.voucherScopeBadge}>
                      {v.store_id ? v.storeName : 'ToÃ n sÃ n'}
                    </Text>
                    <Text style={styles.voucherCodeText}>{v.code}</Text>
                    <Text style={styles.voucherDescText} numberOfLines={2}>
                      {v.title}
                    </Text>
                    <Text style={styles.voucherMinText}>
                      ÄÆ¡n tá»« {formatCurrency(v.minOrder)}
                    </Text>
                  </TouchableOpacity>
                );
              })}
          </ScrollView>
        </View>

        <View style={styles.sectionCard}>
          <Text style={styles.sectionTitle}>Äá»‹a chá»‰ nháº­n hÃ ng</Text>

          <Text style={styles.inputLabel}>NgÆ°á»i nháº­n</Text>
          <TextInput
            style={styles.input}
            placeholder="Há» vÃ  tÃªn..."
            value={customerName}
            onChangeText={setCustomerName}
          />

          <Text style={styles.inputLabel}>Sá»‘ Ä‘iá»‡n thoáº¡i</Text>
          <TextInput
            style={styles.input}
            placeholder="Sá»‘ Ä‘iá»‡n thoáº¡i nháº­n..."
            value={phone}
            onChangeText={setPhone}
            keyboardType="phone-pad"
          />

          <Text style={styles.inputLabel}>Äá»‹a chá»‰ giao</Text>
          <TextInput
            style={styles.input}
            placeholder="Sá»‘ nhÃ , tÃªn Ä‘Æ°á»ng hoáº·c báº¥m Ä‘á»‹nh vá»‹..."
            value={address}
            onChangeText={setAddress}
          />

          <View style={styles.gpsActionRow}>
            <TouchableOpacity
              style={styles.gpsBtn}
              onPress={handleGetRealGPS}
              disabled={loadingGps}
            >
              {loadingGps ? (
                <ActivityIndicator color="#FFF" size="small" />
              ) : (
                <Text style={styles.gpsBtnText}>ðŸ“ Láº¥y vá»‹ trÃ­ GPS</Text>
              )}
            </TouchableOpacity>
          </View>

          {showVirtualMap && (
            <View style={styles.mapListContainer}>
              <Text style={styles.mapListHeader}>Gá»£i Ã½ Ä‘á»‹a Ä‘iá»ƒm nháº­n hÃ ng:</Text>
              {VIRTUAL_MAP_LOCATIONS.map((loc) => (
                <TouchableOpacity
                  key={loc.id}
                  style={styles.mapListItem}
                  onPress={() => {
                    setAddress(loc.address);
                    setShowVirtualMap(false);
                  }}
                >
                  <Text style={styles.mapListTitle}>{loc.title}</Text>
                  <Text style={styles.mapListAddr}>{loc.address}</Text>
                </TouchableOpacity>
              ))}
            </View>
          )}

          <Text style={styles.inputLabel}>Ghi chÃº Ä‘Æ¡n hÃ ng</Text>
          <TextInput
            style={styles.input}
            placeholder="VÃ­ dá»¥: Giao giá» trÆ°a, gá»i trÆ°á»›c khi Ä‘áº¿n..."
            value={note}
            onChangeText={setNote}
          />
        </View>

        <View style={styles.sectionCard}>
          <Text style={styles.sectionTitle}>PhÆ°Æ¡ng thá»©c thanh toÃ¡n</Text>
          <View style={styles.paymentRow}>
            <TouchableOpacity
              style={[
                styles.paymentOption,
                paymentMethod === 'COD' && styles.paymentOptionActive,
              ]}
              onPress={() => setPaymentMethod('COD')}
            >
              <Text
                style={[
                  styles.paymentOptionText,
                  paymentMethod === 'COD' && styles.paymentOptionTextActive,
                ]}
              >
                ðŸ’µ Tiá»n máº·t
              </Text>
            </TouchableOpacity>

            <TouchableOpacity
              style={[
                styles.paymentOption,
                paymentMethod === 'Chuyá»ƒn khoáº£n QR' && styles.paymentOptionActive,
              ]}
              onPress={() => setPaymentMethod('Chuyá»ƒn khoáº£n QR')}
            >
              <Text
                style={[
                  styles.paymentOptionText,
                  paymentMethod === 'Chuyá»ƒn khoáº£n QR' && styles.paymentOptionTextActive,
                ]}
              >
                ðŸ¦ Chuyá»ƒn khoáº£n QR
              </Text>
            </TouchableOpacity>
          </View>

          <View style={styles.summaryBox}>
            <View style={styles.summaryRow}>
              <Text style={styles.summaryLabel}>Táº¡m tÃ­nh:</Text>
              <Text style={styles.summaryVal}>{formatCurrency(subTotal)}</Text>
            </View>
            <View style={styles.summaryRow}>
              <Text style={styles.summaryLabel}>
                Giáº£m giÃ¡ {appliedVoucher ? `(${appliedVoucher.code})` : ''}:
              </Text>
              <Text style={[styles.summaryVal, { color: '#2E7D32' }]}>
                -{formatCurrency(discountAmount)}
              </Text>
            </View>
            <View style={[styles.summaryRow, styles.totalRow]}>
              <Text style={styles.totalLabel}>Tá»•ng thanh toÃ¡n:</Text>
