import React, { useState, useMemo } from 'react';
import {
  View,
  Text,
  TextInput,
  TouchableOpacity,
  FlatList,
  Image,
  ScrollView,
  StyleSheet,
  RefreshControl,
} from 'react-native';
import { SafeAreaView } from 'react-native-safe-area-context';
import { useApp } from '../context/AppContext';
import { CATEGORIES } from '../constants/data';

export default function HomeScreen({ navigation }) {
  const {
    currentUser,
    products,
    stores,
    cart,
    favorites,
    toggleFavorite,
    loading,
    fetchAllData,
  } = useApp();

  const isCustomerOrGuest = !currentUser || currentUser.role === 'customer';

  const [searchQuery, setSearchQuery] = useState('');
  const [selectedCategory, setSelectedCategory] = useState('Táº¥t cáº£');
  const [selectedStoreId, setSelectedStoreId] = useState(0);
  const [onlyDiscount, setOnlyDiscount] = useState(false);
  const [onlyFavorites, setOnlyFavorites] = useState(false);

  const totalCartItems = useMemo(
    () => cart.reduce((sum, item) => sum + item.quantity, 0),
    [cart]
  );

  const featuredProducts = useMemo(() => {
    return products
      .filter((p) => p.isBestSeller && p.isAvailable)
      .sort((a, b) => b.soldCount - a.soldCount);
  }, [products]);

  const filteredProducts = useMemo(() => {
    return products.filter((item) => {
      const matchKeyword =
        item.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
        (item.storeName && item.storeName.toLowerCase().includes(searchQuery.toLowerCase()));

      const matchCategory =
        selectedCategory === 'Táº¥t cáº£' || item.category === selectedCategory;

      const matchStore =
        selectedStoreId === 0 || Number(item.store_id) === Number(selectedStoreId);

      const matchDiscount =
        !onlyDiscount || (item.discountPrice > 0 && item.discountPrice < item.basePrice);

      const matchFav = !onlyFavorites || favorites.includes(item.id);

      return matchKeyword && matchCategory && matchStore && matchDiscount && matchFav;
    });
  }, [products, searchQuery, selectedCategory, selectedStoreId, onlyDiscount, onlyFavorites, favorites]);

  const formatCurrency = (val) => `${Number(val || 0).toLocaleString('vi-VN')}Ä‘`;

  const getWorkspaceButtonLabel = () => {
    if (!currentUser) return '';
    if (currentUser.role === 'shipper') return 'ðŸ›µ Giao hÃ ng';
    if (currentUser.role === 'vendor') return 'ðŸª Quáº£n lÃ½ quÃ¡n';
    return 'ðŸ›¡ï¸ Quáº£n trá»‹ sÃ n';
  };

  const renderProductCard = ({ item }) => {
    const hasDiscount = item.discountPrice > 0 && item.discountPrice < item.basePrice;
    const displayPrice = hasDiscount ? item.discountPrice : item.basePrice;
    const isFav = favorites.includes(item.id);

    return (
      <TouchableOpacity
        style={[styles.productCard, !item.isAvailable && styles.productCardDisabled]}
        activeOpacity={0.85}
        onPress={() => navigation.navigate('ProductDetail', { product: item })}
      >
        <View style={styles.imageWrapper}>
          <Image source={{ uri: item.image }} style={styles.productImage} />
          {hasDiscount && (
            <View style={styles.discountBadge}>
              <Text style={styles.discountBadgeText}>
                -{Math.round(((item.basePrice - item.discountPrice) / item.basePrice) * 100)}%
              </Text>
            </View>
          )}
          {!item.isAvailable && (
            <View style={styles.outOfStockOverlay}>
              <Text style={styles.outOfStockText}>Táº M Háº¾T</Text>
            </View>
          )}
        </View>

        <View style={styles.productInfo}>
          <View style={styles.storeRow}>
            <Text style={styles.storeTag} numberOfLines={1}>
              {item.storeName || 'Cá»­a hÃ ng Ä‘á»‘i tÃ¡c'}
            </Text>
            {isCustomerOrGuest && (
              <TouchableOpacity onPress={() => toggleFavorite(item.id)}>
                <Text style={styles.favIcon}>{isFav ? 'â¤ï¸' : 'ðŸ¤'}</Text>
              </TouchableOpacity>
            )}
          </View>

          <Text style={styles.productName} numberOfLines={1}>
            {item.name}
          </Text>

          <Text style={styles.metaText}>
            â­ {item.avgRating || '5.0'} â€¢ ÄÃ£ bÃ¡n {item.soldCount || 0}
          </Text>

          <View style={styles.priceRow}>
            <View style={{ flexDirection: 'row', alignItems: 'center', gap: 6 }}>
              <Text style={styles.currentPrice}>{formatCurrency(displayPrice)}</Text>
              {hasDiscount && (
                <Text style={styles.oldPrice}>{formatCurrency(item.basePrice)}</Text>
              )}
            </View>

            <View
              style={[
                styles.addMiniBtn,
                !isCustomerOrGuest && { backgroundColor: '#5D4037' },
                !item.isAvailable && { backgroundColor: '#BDBDBD' },
              ]}
            >
              <Text style={styles.addMiniBtnText}>
                {!isCustomerOrGuest ? 'Xem' : item.isAvailable ? '+ Chá»n' : 'Háº¿t'}
              </Text>
            </View>
          </View>
        </View>
      </TouchableOpacity>
    );
  };

  return (
    <SafeAreaView style={styles.safeArea}>
      <View style={styles.header}>
        <View style={{ flex: 1 }}>
          <Text style={styles.headerTitle}>TrÃ  Sá»¯a & CÃ  PhÃª</Text>
          <Text style={styles.headerSubtitle}>
            {currentUser
              ? `${currentUser.fullName} â€¢ ${currentUser.role.toUpperCase()}`
              : 'ÄÄƒng nháº­p Ä‘á»ƒ nháº­n Æ°u Ä‘Ã£i'}
          </Text>
        </View>

        <View style={styles.headerActions}>
          {isCustomerOrGuest ? (
            <>
              {currentUser && (
                <TouchableOpacity
                  style={styles.headerBtn}
                  onPress={() => navigation.navigate('OrderHistory')}
                >
                  <Text style={styles.headerBtnText}>ðŸ“¦ ÄÆ¡n mua</Text>
                </TouchableOpacity>
              )}

              <TouchableOpacity
                style={styles.headerBtn}
                onPress={() =>
                  navigation.navigate(currentUser ? 'Profile' : 'Login')
                }
              >
                <Text style={styles.headerBtnText}>
                  {currentUser ? 'ðŸ‘¤ Há»“ sÆ¡' : 'ÄÄƒng nháº­p'}
                </Text>
              </TouchableOpacity>

              <TouchableOpacity
                style={[styles.headerBtn, styles.cartBtn]}
                onPress={() => navigation.navigate('Cart')}
              >
                <Text style={styles.cartBtnText}>ðŸ›’ {totalCartItems}</Text>
              </TouchableOpacity>
            </>
          ) : (
            <>
              <TouchableOpacity
                style={[styles.headerBtn, { backgroundColor: '#FFD54F' }]}
                onPress={() => navigation.navigate('Admin')}
              >
                <Text style={[styles.headerBtnText, { color: '#3E2723', fontWeight: 'bold' }]}>
                  {getWorkspaceButtonLabel()}
                </Text>
              </TouchableOpacity>

              <TouchableOpacity
                style={styles.headerBtn}
                onPress={() => navigation.navigate('Profile')}
              >
                <Text style={styles.headerBtnText}>ðŸ‘¤ Há»“ sÆ¡</Text>
              </TouchableOpacity>
            </>
          )}
        </View>
      </View>

      {!isCustomerOrGuest && (
        <TouchableOpacity
          style={styles.operatorNoticeBar}
          onPress={() => navigation.navigate('Admin')}
        >
          <Text style={styles.operatorNoticeText}>
            âš¡ Äang xem á»Ÿ vai trÃ² {currentUser.role.toUpperCase()} â€¢ Cháº¡m Ä‘á»ƒ má»Ÿ Báº£ng Ä‘iá»u khiá»ƒn âž”
          </Text>
        </TouchableOpacity>
      )}

      <View style={styles.searchContainer}>
        <TextInput
          style={styles.searchInput}
          placeholder="TÃ¬m Ä‘á»“ uá»‘ng, quÃ¡n Äƒn..."
          value={searchQuery}
          onChangeText={setSearchQuery}
        />
        {searchQuery.length > 0 && (
          <TouchableOpacity
            style={styles.clearSearchBtn}
            onPress={() => setSearchQuery('')}
          >
            <Text style={{ color: '#666', fontWeight: 'bold' }}>âœ•</Text>
          </TouchableOpacity>
        )}
      </View>

      <FlatList
        data={filteredProducts}
        keyExtractor={(item) => item.id.toString()}
        renderItem={renderProductCard}
        contentContainerStyle={styles.listContent}
        refreshControl={
          <RefreshControl refreshing={loading} onRefresh={fetchAllData} colors={['#6F4E37']} />
        }
        ListHeaderComponent={
          <View>
            <ScrollView
              horizontal
              showsHorizontalScrollIndicator={false}
              style={styles.quickFilterScroll}
            >
              <TouchableOpacity
                style={[
                  styles.filterChip,
                  onlyDiscount && styles.filterChipDiscountActive,
                ]}
                onPress={() => setOnlyDiscount(!onlyDiscount)}
              >
                <Text
                  style={[
                    styles.filterChipText,
                    onlyDiscount && { color: '#FFF' },
                  ]}
                >
                  ðŸ”¥ Giáº£m giÃ¡
                </Text>
              </TouchableOpacity>

              {isCustomerOrGuest && (
                <TouchableOpacity
                  style={[
                    styles.filterChip,
                    onlyFavorites && styles.filterChipFavActive,
                  ]}
                  onPress={() => setOnlyFavorites(!onlyFavorites)}
                >
                  <Text
                    style={[
                      styles.filterChipText,
                      onlyFavorites && { color: '#FFF' },
                    ]}
                  >
                    â¤ï¸ YÃªu thÃ­ch
                  </Text>
                </TouchableOpacity>
              )}

              <TouchableOpacity
                style={[
                  styles.filterChip,
                  selectedStoreId === 0 && styles.filterChipStoreActive,
                ]}
                onPress={() => setSelectedStoreId(0)}
              >
                <Text
                  style={[
                    styles.filterChipText,
                    selectedStoreId === 0 && { color: '#FFF' },
                  ]}
                >
                  Táº¥t cáº£ quÃ¡n
                </Text>
              </TouchableOpacity>

              {stores.map((st) => (
                <TouchableOpacity
                  key={st.id}
                  style={[
                    styles.filterChip,
                    Number(selectedStoreId) === Number(st.id) &&
                      styles.filterChipStoreActive,
                  ]}
                  onPress={() => setSelectedStoreId(Number(st.id))}
                >
                  <Text
                    style={[
                      styles.filterChipText,
                      Number(selectedStoreId) === Number(st.id) && { color: '#FFF' },
                    ]}
                  >
                    {st.storeName}
                  </Text>
                </TouchableOpacity>
              ))}
            </ScrollView>

            <ScrollView
              horizontal
              showsHorizontalScrollIndicator={false}
              style={styles.categoryScroll}
            >
              {CATEGORIES.map((cat) => (
                <TouchableOpacity
                  key={cat}
                  style={[
                    styles.categoryTab,
                    selectedCategory === cat && styles.categoryTabActive,
                  ]}
                  onPress={() => setSelectedCategory(cat)}
                >
                  <Text
                    style={[
                      styles.categoryTabText,
                      selectedCategory === cat && styles.categoryTabTextActive,
                    ]}
                  >
                    {cat}
                  </Text>
                </TouchableOpacity>
              ))}
            </ScrollView>

            {searchQuery.trim() === '' &&
              selectedCategory === 'Táº¥t cáº£' &&
              !onlyDiscount &&
              !onlyFavorites &&
              featuredProducts.length > 0 && (
                <View style={styles.featuredSection}>
                  <Text style={styles.sectionTitle}>ðŸ† BÃ¡n Cháº¡y Nháº¥t</Text>

                  <ScrollView horizontal showsHorizontalScrollIndicator={false}>
                    {featuredProducts.map((fp) => {
                      const hasSale = fp.discountPrice > 0 && fp.discountPrice < fp.basePrice;
                      const price = hasSale ? fp.discountPrice : fp.basePrice;
                      return (
                        <TouchableOpacity
                          key={fp.id}
                          style={styles.featuredCard}
                          onPress={() =>
                            navigation.navigate('ProductDetail', { product: fp })
                          }
                        >
                          <Image source={{ uri: fp.image }} style={styles.featuredImg} />
                          <View style={styles.featuredBadge}>
                            <Text style={styles.featuredBadgeText}>
                              ÄÃ£ bÃ¡n {fp.soldCount}
                            </Text>
                          </View>
                          <Text style={styles.featuredStore} numberOfLines={1}>
                            {fp.storeName}
                          </Text>
                          <Text style={styles.featuredName} numberOfLines={1}>
                            {fp.name}
                          </Text>
                          <Text style={styles.featuredPrice}>{formatCurrency(price)}</Text>
                        </TouchableOpacity>
                      );
                    })}
                  </ScrollView>
                </View>
              )}

            <Text style={[styles.sectionTitle, { marginTop: 10, marginBottom: 8 }]}>
