} from 'react-native';
import { useApp } from '../context/AppContext';

export default function LoginScreen({ navigation, route }) {
  const { login } = useApp();
  const redirectTo = route.params?.redirectTo || 'Home';

  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [submitting, setSubmitting] = useState(false);

  const handleLogin = async () => {
  if (!username.trim() || !password.trim()) {
    Alert.alert('Thiáº¿u thÃ´ng tin', 'Vui lÃ²ng nháº­p Ä‘áº§y Ä‘á»§ tÃªn Ä‘Äƒng nháº­p vÃ  máº­t kháº©u!');
    return;
  }

  setSubmitting(true);
  const res = await login(username.trim(), password.trim());
  setSubmitting(false);

  if (res.success) {
    const userRole = res.user.role;
    // KhÃ¡ch hÃ ng vá» trang mua sáº¯m (Home/Cart), cÃ²n Admin/Vendor/Shipper vÃ o tháº³ng Báº£ng Ä‘iá»u khiá»ƒn
    const targetScreen = userRole === 'customer' ? redirectTo : 'Admin';
    navigation.replace(targetScreen);
  } else {
    Alert.alert('ÄÄƒng nháº­p tháº¥t báº¡i', res.message);
  }
};

  const fillDemoAccount = (demoUser, demoPass) => {
    setUsername(demoUser);
    setPassword(demoPass);
  };

  return (
    <KeyboardAvoidingView
      style={styles.container}
      behavior={Platform.OS === 'ios' ? 'padding' : undefined}
    >
      <ScrollView contentContainerStyle={styles.scrollContent}>
        <View style={styles.card}>
          <Text style={styles.brandIcon}>ðŸ§‹</Text>
          <Text style={styles.title}>SÃ n F&B Äa Cá»­a HÃ ng</Text>
          <Text style={styles.subtitle}>
            Äá»“ uá»‘ng ngon, giao nhanh, giÃ¡ tá»‘t vÃ  nhiá»u khuyáº¿n mÃ£i!
          </Text>

          <Text style={styles.label}>TÃªn Ä‘Äƒng nháº­p</Text>
          <TextInput
            style={styles.input}
            placeholder="Nháº­p username"
            value={username}
            onChangeText={setUsername}
            autoCapitalize="none"
          />

          <Text style={styles.label}>Máº­t kháº©u</Text>
          <TextInput
            style={styles.input}
            placeholder="Nháº­p máº­t kháº©u"
            value={password}
            onChangeText={setPassword}
            secureTextEntry
          />

          <TouchableOpacity
            style={styles.loginBtn}
            onPress={handleLogin}
            disabled={submitting}
          >
            {submitting ? (
              <ActivityIndicator color="#FFF" />
            ) : (
              <Text style={styles.loginBtnText}>ÄÄ‚NG NHáº¬P</Text>
            )}
          </TouchableOpacity>

          <TouchableOpacity
            style={styles.registerLink}
            onPress={() => navigation.navigate('Register', { redirectTo })}
          >
            <Text style={styles.registerLinkText}>
              ChÆ°a cÃ³ tÃ i khoáº£n? <Text style={styles.boldText}>ÄÄƒng kÃ½ ngay</Text>
            </Text>
          </TouchableOpacity>

          <View style={styles.demoSection}>
            <Text style={styles.demoTitle}>Test nhanh: Chá»n tÃ i khoáº£n cÃ³ sáºµn</Text>
            <View style={styles.demoRow}>
              <TouchableOpacity
                style={[styles.demoBadge, { backgroundColor: '#E8F5E9' }]}
                onPress={() => fillDemoAccount('khach1', '123456')}
              >
                <Text style={[styles.demoBadgeText, { color: '#2E7D32' }]}>
                  ðŸ‘¤ KhÃ¡ch
                </Text>
              </TouchableOpacity>

              <TouchableOpacity
                style={[styles.demoBadge, { backgroundColor: '#FFF3E0' }]}
                onPress={() => fillDemoAccount('vendor1', '123456')}
              >
                <Text style={[styles.demoBadgeText, { color: '#EF6C00' }]}>
                  ðŸª QuÃ¡n
                </Text>
              </TouchableOpacity>

              <TouchableOpacity
                style={[styles.demoBadge, { backgroundColor: '#E3F2FD' }]}
                onPress={() => fillDemoAccount('shipper1', '123456')}
              >
                <Text style={[styles.demoBadgeText, { color: '#1565C0' }]}>
                  ðŸ›µ TÃ i xáº¿
                </Text>
              </TouchableOpacity>

              <TouchableOpacity
                style={[styles.demoBadge, { backgroundColor: '#FCE4EC' }]}
                onPress={() => fillDemoAccount('admin', '123456')}
              >
                <Text style={[styles.demoBadgeText, { color: '#C2185B' }]}>
                  ðŸ›¡ï¸ Admin
                </Text>
