import React, { useMemo } from 'react';
import {
  View,
  Text,
  FlatList,
  TouchableOpacity,
  StyleSheet,
  Alert,
  RefreshControl,
} from 'react-native';
import { useApp } from '../context/AppContext';
import { ORDER_STATUS_STEPS } from '../constants/data';

export default function OrderHistoryScreen({ navigation }) {
  const {
    currentUser,
    orders,
    products,
    loading,
    fetchAllData,
    updateOrderStatus,
    reOrder,
  } = useApp();

  // Lá»c danh sÃ¡ch Ä‘Æ¡n hÃ ng theo Ä‘Ãºng vai trÃ² Ä‘Äƒng nháº­p
  const myOrders = useMemo(() => {
    if (!currentUser) return [];
    if (currentUser.role === 'admin') return orders;
    if (currentUser.role === 'shipper') {
      return orders.filter(
        (o) =>
          o.shipper_username === currentUser.username ||
          o.status === 'Chá» tÃ i xáº¿ nháº­n'
      );
    }
    if (currentUser.role === 'vendor' && currentUser.store) {
      return orders.filter(
        (o) =>
          Number(o.store_id) === Number(currentUser.store.id) ||
          o.username === currentUser.username
      );
    }
    return orders.filter((o) => o.username === currentUser.username);
  }, [orders, currentUser]);

  const formatCurrency = (val) => `${Number(val || 0).toLocaleString('vi-VN')}Ä‘`;

  const handleCancelOrder = (orderCode) => {
    Alert.alert(
      'XÃ¡c nháº­n há»§y Ä‘Æ¡n',
      `Báº¡n cÃ³ cháº¯c cháº¯n muá»‘n há»§y Ä‘Æ¡n hÃ ng #${orderCode} khÃ´ng?`,
      [
        { text: 'KhÃ´ng', style: 'cancel' },
        {
          text: 'Há»§y Ä‘Æ¡n nÃ y',
          style: 'destructive',
          onPress: async () => {
            const res = await updateOrderStatus(orderCode, 'ÄÃ£ há»§y');
            if (res.success) {
              Alert.alert('ÄÃ£ há»§y', `ÄÆ¡n hÃ ng #${orderCode} Ä‘Ã£ Ä‘Æ°á»£c há»§y.`);
            } else {
              Alert.alert('Lá»—i', res.message);
            }
          },
        },
      ]
    );
  };

  const handleReOrder = (items) => {
    reOrder(items);
    Alert.alert('ÄÃ£ thÃªm vÃ o giá»!', 'ToÃ n bá»™ mÃ³n trong Ä‘Æ¡n cÅ© Ä‘Ã£ Ä‘Æ°á»£c Ä‘Æ°a vÃ o giá» hÃ ng.', [
      { text: 'á»ž láº¡i trang nÃ y', style: 'cancel' },
      { text: 'Äi tá»›i Giá» hÃ ng', onPress: () => navigation.navigate('Cart') },
    ]);
  };

  const handleNavigateReview = (item, orderCode) => {
    const foundProduct = products.find((p) => Number(p.id) === Number(item.productId));
    if (foundProduct) {
      navigation.navigate('ProductDetail', {
        product: foundProduct,
        orderCode,
      });
    } else {
      Alert.alert('ThÃ´ng bÃ¡o', 'Sáº£n pháº©m nÃ y hiá»‡n Ä‘Ã£ bá»‹ gá»¡ khá»i ká»‡!');
    }
  };

  if (!currentUser) {
    return (
      <View style={styles.emptyBox}>
        <Text style={styles.emptyEmoji}>ðŸ“¦</Text>
        <Text style={styles.emptyTitle}>Vui lÃ²ng Ä‘Äƒng nháº­p</Text>
        <Text style={styles.emptySub}>
          ÄÄƒng nháº­p Ä‘á»ƒ theo dÃµi tiáº¿n trÃ¬nh giao hÃ ng 4 bÆ°á»›c vÃ  lá»‹ch sá»­ Ä‘áº·t mÃ³n.
        </Text>
        <TouchableOpacity
          style={styles.primaryBtn}
          onPress={() => navigation.navigate('Login', { redirectTo: 'OrderHistory' })}
        >
          <Text style={styles.primaryBtnText}>ÄÄ‚NG NHáº¬P NGAY</Text>
        </TouchableOpacity>
      </View>
    );
  }

  const renderOrderCard = ({ item: order }) => {
    const isCancelled = order.status === 'ÄÃ£ há»§y';
    const currentStepIndex = ORDER_STATUS_STEPS.indexOf(order.status);
    const isPaidQR =
      order.paymentMethod?.includes('QR') ||
      order.paymentStatus?.includes('QR');

    return (
      <View style={styles.orderCard}>
