            <Text style={styles.orderCodeText}>MÃ£ Ä‘Æ¡n: #{order.orderCode}</Text>
            <Text style={styles.storeNameText}>
              ðŸª {order.storeName || `Cá»­a hÃ ng #${order.store_id}`}
            </Text>
          </View>

          <View
            style={[
              styles.statusBadge,
