          </View>
        </View>

        {/* Thanh tiáº¿n trÃ¬nh 4 bÆ°á»›c (QuÃ¡n chuáº©n bá»‹ -> Chá» Shipper -> Äang giao -> HoÃ n táº¥t) */}
        {!isCancelled && (
          <View style={styles.timelineContainer}>
            {ORDER_STATUS_STEPS.map((step, idx) => {
              const active = idx <= currentStepIndex;
              return (
