              );
            })}
          </View>
        )}

        {/* ThÃ´ng tin TÃ i xáº¿ giao hÃ ng (náº¿u Ä‘Ã£ cÃ³ Shipper nháº­n Ä‘Æ¡n) */}
        {order.shipperName ? (
          <View style={styles.shipperBanner}>
            <Text style={styles.shipperBannerText}>
              ðŸ›µ TÃ i xáº¿ phá»¥ trÃ¡ch: <Text style={{ fontWeight: 'bold' }}>{order.shipperName}</Text>{' '}
              (@{order.shipper_username})
            </Text>
          </View>
        ) : order.status === 'Chá» tÃ i xáº¿ nháº­n' ? (
          <View style={[styles.shipperBanner, { backgroundColor: '#FFF8E1' }]}>
            <Text style={[styles.shipperBannerText, { color: '#E65100' }]}>
              â³ QuÃ¡n Ä‘Ã£ pha cháº¿ xong, Ä‘ang chá» TÃ i xáº¿ (Shipper) nháº­n Ä‘Æ¡n...
            </Text>
          </View>
        ) : null}

        {/* Danh sÃ¡ch mÃ³n nÆ°á»›c trong Ä‘Æ¡n */}
        <View style={styles.itemsBox}>
          {(order.items || []).map((prod, index) => (
            <View key={index} style={styles.itemRow}>
              <View style={{ flex: 1 }}>
                <Text style={styles.itemName}>
                  {prod.quantity}x {prod.name} (Size {prod.size})
                </Text>
                <Text style={styles.itemSub}>
                  {prod.sugar} Ä‘Æ°á»ng â€¢ {prod.ice}
                  {prod.toppings && prod.toppings.length > 0
                    ? ` â€¢ +${prod.toppings.join(', ')}`
                    : ''}
                </Text>
              </View>

              <View style={{ alignItems: 'flex-end' }}>
                <Text style={styles.itemPrice}>
                  {formatCurrency(prod.totalPrice)}
                </Text>
                {order.status === 'HoÃ n táº¥t' &&
                  currentUser.username === order.username && (
                    <TouchableOpacity
                      style={styles.reviewMiniBtn}
                      onPress={() => handleNavigateReview(prod, order.orderCode)}
                    >
                      <Text style={styles.reviewMiniBtnText}>â­ ÄÃ¡nh giÃ¡ mÃ³n</Text>
                    </TouchableOpacity>
                  )}
              </View>
            </View>
          ))}
        </View>

        {/* ThÃ´ng tin giao nháº­n & Tráº¡ng thÃ¡i Thanh toÃ¡n */}
        <View style={styles.metaBox}>
          <Text style={styles.metaLine}>
            ðŸ“ Giao Ä‘áº¿n: {order.customerName} ({order.phone}) - {order.address}
          </Text>
          {order.voucherCode ? (
            <Text style={styles.metaLine}>
              ðŸŽŸï¸ Voucher Ã¡p dá»¥ng: {order.voucherCode} (-
              {formatCurrency(order.discountAmount)})
            </Text>
          ) : null}

          <View style={styles.totalRow}>
            <View>
              <Text style={styles.paymentMethodText}>
                HÃ¬nh thá»©c: {order.paymentMethod}
              </Text>
              <Text
                style={[
                  styles.paymentStatusBadge,
                  isPaidQR ? { color: '#1565C0' } : { color: '#2E7D32' },
                ]}
              >
                {isPaidQR ? 'âœ… ' : 'ðŸ’µ '}
                {order.paymentStatus || order.paymentMethod}
              </Text>
            </View>
            <Text style={styles.totalAmountText}>
              Tá»•ng: {formatCurrency(order.totalAmount)}
            </Text>
          </View>
        </View>

        {/* CÃ¡c nÃºt thao tÃ¡c dÃ nh cho KhÃ¡ch hÃ ng */}
        <View style={styles.actionRow}>
          <TouchableOpacity
            style={styles.reOrderBtn}
            onPress={() => handleReOrder(order.items)}
          >
            <Text style={styles.reOrderBtnText}>ðŸ”„ Äáº·t láº¡i Ä‘Æ¡n nÃ y</Text>
          </TouchableOpacity>

          {order.status === 'Äang chuáº©n bá»‹' &&
            currentUser.username === order.username && (
              <TouchableOpacity
                style={styles.cancelBtn}
                onPress={() => handleCancelOrder(order.orderCode)}
