      storeName: product.storeName || 'Cá»­a hÃ ng Ä‘á»‘i tÃ¡c',
      image: product.image,
      size: selectedSize.id,
      sugar: selectedSugar,
      ice: selectedIce,
      toppings: selectedToppings.map((t) => t.name),
      quantity,
      unitPrice,
      totalPrice,
    });

    Alert.alert('ThÃ nh cÃ´ng', `ÄÃ£ thÃªm ${quantity}x ${product.name} vÃ o giá» hÃ ng.`, [
      { text: 'Chá»n tiáº¿p', style: 'cancel' },
      { text: 'Xem giá» hÃ ng', onPress: () => navigation.navigate('Cart') },
    ]);
  };

  const handleSubmitReview = async () => {
    if (!eligibleOrderCode) {
      Alert.alert(
        'ThÃ´ng bÃ¡o',
        'Báº¡n chá»‰ cÃ³ thá»ƒ Ä‘Ã¡nh giÃ¡ sau khi Ä‘Æ¡n hÃ ng Ä‘Ã£ á»Ÿ tráº¡ng thÃ¡i HoÃ n táº¥t.'
      );
      return;
    }
    if (!comment.trim()) {
      Alert.alert('Thiáº¿u ná»™i dung', 'Vui lÃ²ng nháº­p cáº£m nháº­n cá»§a báº¡n vá» mÃ³n nÆ°á»›c nÃ y!');
      return;
    }

    setSubmittingReview(true);
    const res = await addReview({
      orderCode: eligibleOrderCode,
      product_id: product.id,
      rating,
      comment: comment.trim(),
    });
    setSubmittingReview(false);

    if (res.success) {
      setComment('');
      Alert.alert('ThÃ nh cÃ´ng', res.message);
    } else {
      Alert.alert('Lá»—i', res.message);
