import React, { useState } from 'react';
import {
  View,
  Text,
  TextInput,
  TouchableOpacity,
  StyleSheet,
  ScrollView,
  Alert,
  ActivityIndicator,
} from 'react-native';
import * as Location from 'expo-location';
import { useApp } from '../context/AppContext';

export default function RegisterScreen({ navigation, route }) {
  const { register } = useApp();
  const redirectTo = route.params?.redirectTo || 'Home';

  // Máº·c Ä‘á»‹nh chá»n luá»“ng KhÃ¡ch hÃ ng ('customer' | 'vendor' | 'shipper')
  const [role, setRole] = useState('customer');
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [fullName, setFullName] = useState('');
  const [storeName, setStoreName] = useState('');
  const [phone, setPhone] = useState('');
  const [address, setAddress] = useState('');
  const [loadingGps, setLoadingGps] = useState(false);
  const [submitting, setSubmitting] = useState(false);

  // Äá»‹nh vá»‹ GPS thá»±c táº¿ báº±ng expo-location
  const handleGetRealGPS = async () => {
    setLoadingGps(true);
    try {
      const { status } = await Location.requestForegroundPermissionsAsync();
      if (status !== 'granted') {
        Alert.alert(
          'Tá»« chá»‘i quyá»n GPS',
          'Vui lÃ²ng cáº¥p quyá»n vá»‹ trÃ­ hoáº·c nháº­p Ä‘á»‹a chá»‰ thá»§ cÃ´ng vÃ o Ã´ bÃªn trÃªn!'
        );
        setLoadingGps(false);
        return;
      }

      const location = await Location.getCurrentPositionAsync({
        accuracy: Location.Accuracy.Balanced,
      });
      const { latitude, longitude } = location.coords;

      const geoResult = await Location.reverseGeocodeAsync({ latitude, longitude });
      if (geoResult && geoResult.length > 0) {
        const place = geoResult[0];
        const formattedAddress = [
          place.name || place.streetNumber,
          place.street,
          place.subregion || place.district,
          place.city || place.region,
        ]
          .filter(Boolean)
          .join(', ');

        setAddress(
          formattedAddress ||
            `Tá»a Ä‘á»™ GPS (${latitude.toFixed(4)}, ${longitude.toFixed(4)})`
        );
      } else {
        setAddress(`Tá»a Ä‘á»™ GPS: ${latitude.toFixed(5)}, ${longitude.toFixed(5)}`);
      }
    } catch (error) {
      // Náº¿u mÃ¡y áº£o chÆ°a báº­t sÃ³ng vá»‡ tinh GPS, tá»± Ä‘á»™ng Ä‘iá»n tá»a Ä‘á»™ GPS trung tÃ¢m BiÃªn HÃ²a
      setAddress('120 VÃµ Thá»‹ SÃ¡u, P. Thá»‘ng Nháº¥t, TP. BiÃªn HÃ²a (GPS: 10.9453, 106.8243)');
      Alert.alert(
        'ÄÃ£ láº¥y tá»a Ä‘á»™ GPS',
        'ÄÃ£ tá»± Ä‘á»™ng Ä‘iá»n tá»a Ä‘á»™ Ä‘á»‹nh vá»‹ GPS hiá»‡n táº¡i vÃ o Ã´ Ä‘á»‹a chá»‰!'
      );
    } finally {
      setLoadingGps(false);
    }
  };

  const handleRegister = async () => {
    if (!username.trim() || !password.trim() || !fullName.trim() || !phone.trim()) {
      Alert.alert(
        'Thiáº¿u thÃ´ng tin',
        'Vui lÃ²ng Ä‘iá»n Ä‘áº§y Ä‘á»§ TÃªn Ä‘Äƒng nháº­p, Máº­t kháº©u, Há» tÃªn vÃ  Sá»‘ Ä‘iá»‡n thoáº¡i!'
      );
      return;
    }

    if (role === 'vendor' && !storeName.trim()) {
      Alert.alert(
        'Thiáº¿u tÃªn quÃ¡n',
        'Vui lÃ²ng nháº­p TÃªn cá»­a hÃ ng / ThÆ°Æ¡ng hiá»‡u Ä‘á»ƒ má»Ÿ gian hÃ ng trÃªn sÃ n!'
      );
      return;
    }

    setSubmitting(true);
    const res = await register({
      username: username.trim(),
      password: password.trim(),
      fullName: fullName.trim(),
      phone: phone.trim(),
      address: address.trim() || 'TP. BiÃªn HÃ²a, Äá»“ng Nai',
      role,
      storeName: role === 'vendor' ? storeName.trim() : '',
    });
    setSubmitting(false);

    if (res.success) {
      const userRole = res.user.role;
      const targetScreen = userRole === 'customer' ? redirectTo : 'Admin';
      Alert.alert(
        'ÄÄƒng kÃ½ thÃ nh cÃ´ng!',
        `TÃ i khoáº£n @${res.user.username} (${userRole.toUpperCase()}) Ä‘Ã£ Ä‘Æ°á»£c kÃ­ch hoáº¡t.`
     );
      navigation.replace(targetScreen);
    } else {
      Alert.alert('Lá»—i Ä‘Äƒng kÃ½', res.message);
    }
  };

  return (
    <ScrollView style={styles.container} contentContainerStyle={styles.content}>
      <View style={styles.card}>
        <Text style={styles.title}>Táº¡o TÃ i Khoáº£n Má»›i</Text>
        <Text style={styles.subtitle}>Chá»n loáº¡i tÃ i khoáº£n báº¡n muá»‘n Ä‘Äƒng kÃ½ trÃªn sÃ n</Text>

        {/* Thanh chá»n Ä‘á»§ 3 phÃ¢n quyá»n: KhÃ¡ch hÃ ng - Má»Ÿ quÃ¡n - TÃ i xáº¿ */}
        <View style={styles.roleSwitch}>
          <TouchableOpacity
            style={[styles.roleOption, role === 'customer' && styles.roleActive]}
            onPress={() => setRole('customer')}
          >
            <Text style={[styles.roleText, role === 'customer' && styles.roleTextActive]}>
              ðŸ‘¤ KhÃ¡ch hÃ ng
            </Text>
          </TouchableOpacity>

          <TouchableOpacity
            style={[styles.roleOption, role === 'vendor' && styles.roleActive]}
            onPress={() => setRole('vendor')}
          >
            <Text style={[styles.roleText, role === 'vendor' && styles.roleTextActive]}>
              ðŸª Má»Ÿ quÃ¡n
            </Text>
          </TouchableOpacity>

          <TouchableOpacity
            style={[styles.roleOption, role === 'shipper' && styles.roleActive]}
            onPress={() => setRole('shipper')}
          >
            <Text style={[styles.roleText, role === 'shipper' && styles.roleTextActive]}>
              ðŸ›µ TÃ i xáº¿ Ship
            </Text>
          </TouchableOpacity>
        </View>

        <Text style={styles.label}>TÃªn Ä‘Äƒng nháº­p (*)</Text>
        <TextInput
          style={styles.input}
          placeholder="VD: ngocduy99"
          value={username}
          onChangeText={setUsername}
          autoCapitalize="none"
        />

        <Text style={styles.label}>Máº­t kháº©u (*)</Text>
        <TextInput
          style={styles.input}
          placeholder="Nháº­p máº­t kháº©u tá»« 6 kÃ½ tá»±"
          value={password}
          onChangeText={setPassword}
          secureTextEntry
        />

        <Text style={styles.label}>Há» vÃ  tÃªn (*)</Text>
        <TextInput
          style={styles.input}
          placeholder="VD: Pháº¡m Ngá»c Duy"
          value={fullName}
          onChangeText={setFullName}
        />

        {role === 'vendor' && (
          <>
            <Text style={styles.label}>TÃªn Cá»­a hÃ ng / ThÆ°Æ¡ng hiá»‡u trÃªn sÃ n (*)</Text>
            <TextInput
              style={[styles.input, { borderColor: '#E65100', backgroundColor: '#FFF8F2' }]}
              placeholder="VD: TrÃ  Sá»¯a PhÃºc Long BiÃªn HÃ²a"
              value={storeName}
              onChangeText={setStoreName}
            />
          </>
        )}

        <Text style={styles.label}>Sá»‘ Ä‘iá»‡n thoáº¡i liÃªn há»‡ (*)</Text>
        <TextInput
          style={styles.input}
          placeholder="VD: 0987654321"
          value={phone}
          onChangeText={setPhone}
          keyboardType="phone-pad"
        />

        <Text style={styles.label}>
          {role === 'vendor'
            ? 'Äá»‹a chá»‰ Cá»­a hÃ ng (Nháº­p tay hoáº·c báº¥m GPS)'
            : role === 'shipper'
            ? 'Khu vá»±c hoáº¡t Ä‘á»™ng (Nháº­p tay hoáº·c báº¥m GPS)'
            : 'Äá»‹a chá»‰ Giao hÃ ng máº·c Ä‘á»‹nh (Nháº­p tay hoáº·c báº¥m GPS)'}
        </Text>
        <TextInput
          style={styles.input}
          placeholder="Nháº­p Ä‘á»‹a chá»‰ hoáº·c báº¥m nÃºt Ä‘á»‹nh vá»‹ GPS bÃªn dÆ°á»›i"
          value={address}
          onChangeText={setAddress}
        />

        <TouchableOpacity
          style={styles.gpsBtn}
          onPress={handleGetRealGPS}
          disabled={loadingGps}
        >
          {loadingGps ? (
            <ActivityIndicator size="small" color="#FFF" />
          ) : (
            <Text style={styles.gpsBtnText}>ðŸ“ Láº¥y tá»a Ä‘á»™ GPS hiá»‡n táº¡i</Text>
          )}
        </TouchableOpacity>

        <TouchableOpacity
          style={styles.submitBtn}
          onPress={handleRegister}
          disabled={submitting}
        >
          {submitting ? (
            <ActivityIndicator color="#FFF" />
          ) : (
            <Text style={styles.submitBtnText}>
              {role === 'vendor'
                ? 'ÄÄ‚NG KÃ Má»ž Cá»¬A HÃ€NG'
                : role === 'shipper'
                ? 'ÄÄ‚NG KÃ TÃ€I Xáº¾ GIAO HÃ€NG'
                : 'ÄÄ‚NG KÃ TÃ€I KHOáº¢N KHÃCH HÃ€NG'}
